mkdir -p /work/src /work/test /work/types && cd /work && cat > package.json <<'EOF'
{
  "name": "node-module-resolver",
  "version": "0.1.0",
  "description": "A programmatic implementation of Node.js's CommonJS module resolution algorithm (require.resolve), including package \"exports\" and \"imports\".",
  "type": "module",
  "exports": {
    ".": {
      "types": "./types/index.d.ts",
      "default": "./src/index.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "src",
    "types"
  ],
  "engines": {
    "node": ">=20.19"
  },
  "scripts": {
    "test": "node --test"
  },
  "keywords": [
    "resolve",
    "require.resolve",
    "module-resolution",
    "build-tool"
  ],
  "license": "MIT"
}
EOF
cat > .gitignore <<'EOF'
node_modules/
coverage/
*.log
.DS_Store
EOF
cat > .editorconfig <<'EOF'
root = true

[*]
indent_style = space
indent_size = 2
end_of_line = lf
charset = utf-8
insert_final_newline = true
trim_trailing_whitespace = true
EOF
cat > src/errors.js <<'EOF'
/**
 * Create an Error carrying a Node-style `code` property so callers can
 * branch on the same codes Node's own resolver uses.
 *
 * @param {string} code
 * @param {string} message
 * @param {ErrorConstructor} [ErrorCtor]
 */
export function codedError(code, message, ErrorCtor = Error) {
  const err = new ErrorCtor(message);
  err.code = code;
  return err;
}

export function moduleNotFound(request, basedir) {
  const err = codedError('MODULE_NOT_FOUND', `Cannot find module '${request}' from '${basedir}'`);
  err.request = request;
  err.basedir = basedir;
  return err;
}
EOF

